     ?? throw new InvalidOperationException(
         "Set the OPENAI_API_KEY environment variable before running.");

 const string modelId = "gpt-4o-mini-2024-07-18";

 // --- Build the IChatClient through MEAI ---
 IChatClient chatClient = new OpenAIClient(apiKey)
     .GetChatClient(modelId)
     .AsIChatClient();

 // --- Tool implementations ---
 var notebook = new ResearchNotebook();

 var tools = new AITool[]
 {
     AIFunctionFactory.Create(
         (string query) =>
         {
             Console.WriteLine($"  🔍 Searching: \"{query}\"");
             return WebSearchTool.SearchAsync(query);
         },
         "web_search",
         "Search the web for information on a topic. Returns a list of result snippets."),

     AIFunctionFactory.Create(
         ([Description("A concise heading for this note")] string title,
          [Description("The note content to save")] string content) =>
         {
             notebook.AddNote(title, content);
             Console.WriteLine($"  📝 Note saved: \"{title}\"");
             return $"Note '{title}' saved successfully.";
         },
         "save_note",
         "Save a research note for later use in the summary."),

     AIFunctionFactory.Create(
         () =>
         {
             Console.WriteLine("  📖 Reading all notes...");
             return notebook.GetAllNotes();
         },
         "get_notes",
         "Retrieve all previously saved research notes."),
 };

 // --- Create the agent with Microsoft.Agents.AI ---
 var agent = new ChatClientAgent(
     chatClient,
     name: "ResearchAgent",
     instructions: """
         You are a research agent. Given a topic, you must:
         1. Use web_search to find relevant information (perform 2-3 searches with varied queries).
         2. Use save_note to record key findings from each search.
         3. Use get_notes to review everything you've collected.
         4. Provide a well-structured summary with sections and source attribution.
         Be thorough but concise. Always cite where information came from.
         """,
     tools: tools);

 // --- Main loop ---
 Console.WriteLine("╔══════════════════════════════════════════╗");
 Console.WriteLine("║       🔬 AI Research Agent               ║");
 Console.WriteLine("║  Enter a topic to research, or 'quit'    ║");
 Console.WriteLine("╚══════════════════════════════════════════╝");
 Console.WriteLine();

 while (true)
 {
     Console.Write("Research topic> ");
     var topic = Console.ReadLine()?.Trim();

     if (string.IsNullOrEmpty(topic))
         continue;

     if (topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
         break;

     notebook.Clear();
     Console.WriteLine($"\n🔬 Researching: \"{topic}\"...\n");

     try
     {
         var runOptions = new ChatClientAgentRunOptions(new ChatOptions
         {
             Temperature = 0f,
             MaxOutputTokens = 2048,
         });

         AgentResponse response = await agent.RunAsync(
             $"Research the following topic and provide a comprehensive summary: {topic}",
             session: null,
             options: runOptions);

         Console.WriteLine("\n════════════════ Research Summary ════════════════");
         Console.WriteLine(response.Text);
         Console.WriteLine("══════════════════════════════════════════════════\n");
     }
     catch (Exception ex)
     {
         Console.WriteLine($"\n❌ Error: {ex.Message}\n");
     }
 }

 Console.WriteLine("Goodbye!");

 // --- Supporting types ---

 /// <summary>Simulated web search that uses the OpenAI-compatible endpoint for demo purposes.</summary>
 static class WebSearchTool
 {
     private static readonly HttpClient s_http = new();
     private static readonly string[] s_searchEngineSnippets =
     [
         "According to recent research published in 2025, {0} has seen significant developments.",
         "A comprehensive review on {0} highlights several key aspects worth noting.",
         "Industry experts suggest that {0} is evolving rapidly with new breakthroughs.",
         "Wikipedia states that {0} encompasses multiple interrelated concepts.",
         "Recent academic papers on {0} reveal emerging trends and open questions.",
     ];

     public static Task<string> SearchAsync(string query)
     {
         // Simulated search results for demo — replace with a real search API
         var results = new List<string>();
         var rng = new Random(query.GetHashCode());
         int count = rng.Next(3, 5);

         for (int i = 0; i < count; i++)
         {
             var template = s_searchEngineSnippets[rng.Next(s_searchEngineSnippets.Length)];
             results.Add($"[Result {i + 1}] {string.Format(template, query)} " +
                         $"(Source: search-result-{rng.Next(1000, 9999)}.example.com)");
         }

         return Task.FromResult(string.Join("\n\n", results));
     }
 }

 /// <summary>In-memory notebook for collecting research notes.</summary>
 sealed class ResearchNotebook
 {
     private readonly List<(string Title, string Content, DateTime Timestamp)> _notes = [];

     public void AddNote(string title, string content)
         => _notes.Add((title, content, DateTime.UtcNow));

     public void Clear() => _notes.Clear();

     public string GetAllNotes()
     {
         if (_notes.Count == 0)
             return "No notes saved yet.";

         return string.Join("\n\n", _notes.Select((n, i) =>
             $"--- Note {i + 1}: {n.Title} ---\n{n.Content}"));
     }
 }

